  var right_forward_ = Blockly.Python.valueToCode(block, "right_forward", Blockly.Python.ORDER_ATOMIC);
  var right_reverse_ = Blockly.Python.valueToCode(block, "right_reverse", Blockly.Python.ORDER_ATOMIC);
