// ---- Simulate (simulate.blockdef.yaml) ---------------------------------------

Blockly.Python['simulate_water_boiler'] = function(block) {
  Blockly.Python.definitions_["import_utime"] = "import utime";
  Blockly.Python.definitions_["simulate_water_boiler_class"] = "class WaterBoiler:\n    \"\"\"\n    Simple simulation of a water boiler which can heat up water\n    and where the heat dissipates slowly over time\n    \"\"\"\n\n    def __init__(self, dissipation=0.2):\n        self.water_temp = 20\n        self.ambient = 20\n        self.dissipation = dissipation\n        self._last_time = utime.ticks_ms()\n\n    def update(self, boiler_power):\n        now = utime.ticks_ms()\n        dt = utime.ticks_diff(now,self._last_time) if (utime.ticks_diff(now,self._last_time)) else 1e-16\n        if boiler_power > 0:\n            # Boiler can only produce heat, not cold\n            self.water_temp += 1 * boiler_power * dt / 1000\n\n        # Some heat dissipation\n        self.water_temp -= (self.water_temp - self.ambient) * self.dissipation * dt\n\n        self._last_time = now\n        return self.water_temp";
  var ID_ = block.getFieldValue("ID");
  var DISSIPATION_ = block.getFieldValue("DISSIPATION");
  var POWER_ = Blockly.Python.valueToCode(block, "POWER", Blockly.Python.ORDER_ATOMIC);
  Blockly.Python.definitions_["simulate_water_boiler_obj" + ID_] = "water_boiler" + ID_ + " = WaterBoiler(" + DISSIPATION_ + ")";
  var code = "water_boiler" + ID_ + ".update(" + POWER_ + ")";
  return [code, Blockly.Python.ORDER_NONE];
};

Blockly.Python['simulate_dcmotor.sim'] = function(block) {
  Blockly.Python.definitions_["import_utime"] = "import utime";
  Blockly.Python.definitions_["import_math"] = "import math";
  Blockly.Python.definitions_["simulate_dcmotor_class"] = "class DCMotor:\n\n    def __init__ (\n        self,\n        Ra=0.52,\n        La=0.000036,\n        B=0.00001,\n        J=0.000012,\n        Kbemf=0.0137,\n        STATIC_FRICTION=0.01,\n        FRICTION_S=0.01\n    ):\n        self.bemf = 0.0\n        # omega = rpm ( w )\n        self.omega = 0.0\n\n        # theta = electrical angle normalized to 2*pi\n        self.theta = 0.0\n\n        self.ia, self.va = 0.0, 0.0\n\n        self.Pelec, self.Te, self.Tl = 0.0, 0.0, 0.0\n\n        # La here is La subtracted by mutual inductance M.\n        self.Ra, self.La, self.B, self.J = Ra, La, B, J\n        self.Kbemf = Kbemf\n        self.STATIC_FRICTION, self.FRICTION_S = STATIC_FRICTION, FRICTION_S\n\n        self._last_time = 0.0\n\n\n    # The simulator\n    def sim( self, load, va, dt):\n        now = utime.ticks_us()\n\n        # Set the load\n        sign = math.copysign( 1, self.omega )\n        self.Tl = sign * load\n        self.va = va\n\n        # Calculate bemf\n        self.bemf = self.Kbemf * self.omega\n\n        # Calculate change in current per di/dt\n        dot_ia = (1.0 / self.La) * ( self.va - (self.Ra * self.ia) - self.bemf )\n\n        # Apply changes to current in phases\n        self.ia += dot_ia * dt\n\n        # Electrical torque. Since omega can be null, cannot derive from P/w\n        self.Te = self.Kbemf * self.ia\n\n        # Electrical power\n        self.Pelec = self.bemf * self.ia\n\n\n        # Mechanical torque.\n        # mtorque = ((etorque * (p->m->NbPoles / 2)) - (p->m->damping * sv->omega) - p->pv->torque);\n        self.Tm = ((self.Te) - (sign * self.B * abs(self.omega)) - self.Tl)\n\n        # Friction calculations\n        if abs(self.omega) < 1.0:\n            if abs(self.Te) < self.STATIC_FRICTION:\n                self.Tm = 0.0\n            else:\n                self.Tm -= self.STATIC_FRICTION\n        else:\n            self.Tm = self.Tm - sign * ( self.STATIC_FRICTION * math.exp( -5 * abs( self.omega )) + self.FRICTION_S )\n\n        # J is the moment of inertia\n        dotOmega = (self.Tm / self.J)\n        self.omega = self.omega + dotOmega * dt\n\n\n        self.theta += self.omega * dt\n        self.theta = self.theta % ( 2.0 * math.pi )\n\n        self._last_time += dt\n        return self.omega";
  var ID_ = block.getFieldValue("ID");
  var RA_ = block.getFieldValue("RA");
  var LA_ = block.getFieldValue("LA");
  var B_ = block.getFieldValue("B");
  var J_ = block.getFieldValue("J");
  var KBEMF_ = block.getFieldValue("KBEMF");
  var STATIC_FRICTION_ = block.getFieldValue("STATIC_FRICTION");
  var POWER_ = Blockly.Python.valueToCode(block, "POWER", Blockly.Python.ORDER_ATOMIC);
  var DT_ = Blockly.Python.valueToCode(block, "DT", Blockly.Python.ORDER_ATOMIC);
  var LOAD_ = Blockly.Python.valueToCode(block, "LOAD", Blockly.Python.ORDER_ATOMIC);
  Blockly.Python.definitions_["simulate_dcmotor_obj" + ID_] = "dcmotor" + ID_ + " = DCMotor(" + RA_ + "," + LA_ + "," + B_ + "," + J_ + "," + KBEMF_ + "," + STATIC_FRICTION_ + ",0)";
  var code = "dcmotor" + ID_ + ".sim(" + LOAD_ + ", " + POWER_ + ", " + DT_ + ")";
  return [code, Blockly.Python.ORDER_NONE];
};

