  var duration_ = Blockly.Python.valueToCode(block, "duration", Blockly.Python.ORDER_ATOMIC);
  var code = "\ntone_pwm[" + pin_ + "] = PWM(Pin(" + pin_ + "))\ntone_pwm[" + pin_ + "].freq(" + frequency_ + ")\ntone_pwm[" + pin_ + "].duty_u16(512)\nif " + duration_ + " > 0:\n    time.sleep(" + duration_ + ")\n    tone_pwm[" + pin_ + "].deinit()";
